import test from 'node:test';
import assert from 'node:assert/strict';
import {applyLocales,assertScreeningCopy,assertScreeningRows,SCREENING_BASE,SCREENING_LANGS,SCREENING_KEYS} from './apply-screening.mjs';
test('actual pinned base exposes the five English screening fallbacks',()=>{const l=applyLocales(SCREENING_BASE);for(const lang of SCREENING_LANGS)assert.equal(l.locales[lang].step3Title,l.locales.en.step3Title);assert.throws(()=>assertScreeningCopy(l));});
test('screening copy covers all five languages and20 footer notices; unchanged locale/operating data',()=>{const now=applyLocales(),old=applyLocales(SCREENING_BASE);assertScreeningCopy(now);assert.deepEqual(now.languages,old.languages);assert.deepEqual(now.internal,old.internal);for(const lang of ['pl','ru','uk','en']){const {footerNotice,footerPrivacyLabel,...rest}=now.locales[lang];assert.deepEqual(rest,old.locales[lang]);}for(const lang of SCREENING_LANGS)for(const key of SCREENING_KEYS){const broken=structuredClone(now);broken.locales[lang][key]=now.locales.en[key];assert.throws(()=>assertScreeningCopy(broken));}});
const valid=()=>[320,1280].flatMap(width=>SCREENING_LANGS.map(lang=>({width,lang,status:'passed',steps:true,labels:true,options:true,conditional:true,answers:true,review:true,back:true,resumed:true,fits:true,painted:true,noDelivery:true})));
test('screening browser gate requires10 unique complete visible flows',()=>{assert.doesNotThrow(()=>assertScreeningRows(valid()));for(const rows of [valid().slice(1),valid().map((r,i,a)=>i===1?a[0]:r)])assert.throws(()=>assertScreeningRows(rows));for(const key of ['steps','labels','options','conditional','answers','review','back','resumed','fits','painted','noDelivery']){const rows=valid();rows[0][key]=false;assert.throws(()=>assertScreeningRows(rows));}});
